/**
 * Issue dependencies ("blocked by" links): link management, the completion gate's error type and the unblocked-notification reaction.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as depRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by open issues: ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
  }
}

type BlockerInput = { orgId: OrgId; issueId: IssueId; blockerId: IssueId };

const isClosedStatus = (status: IssueStatus): boolean =>
  status === "done" || status === "canceled";

export async function addBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  if (input.issueId === input.blockerId) {
    throw new Error("An issue cannot block itself");
  }
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await depRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  if (await reaches(input.orgId, input.blockerId, input.issueId)) {
    throw new Error("Adding this blocker would create a dependency cycle");
  }

  return depRepo.insertDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return depRepo.deleteDependency(input.orgId, input.issueId, input.blockerId);
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const found: Issue[] = [];
  for (const id of await depRepo.listBlockerIds(orgId, issueId)) {
    const blocker = await issueRepo.findIssueById(orgId, id);
    if (blocker && !isArchived(blocker)) found.push(blocker);
  }
  return found.sort(
    (a, b) => a.number - b.number || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0),
  );
}

/** True when `target` is reachable from `start` by following blocked-by links. */
async function reaches(
  orgId: OrgId,
  start: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>();
  const stack: IssueId[] = [start];
  while (stack.length > 0) {
    const current = stack.pop() as IssueId;
    if (current === target) return true;
    if (seen.has(current)) continue;
    seen.add(current);
    stack.push(...(await depRepo.listBlockerIds(orgId, current)));
  }
  return false;
}

/** Throws `IssueBlockedError` when `issueId` still has open blockers. */
export async function assertNoOpenBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const open = await depRepo.listOpenBlockerIds(orgId, issueId);
  if (open.length > 0) throw new IssueBlockedError(open);
}

async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: Actor["userId"] | null,
): Promise<void> {
  for (const blockedId of await depRepo.listBlockedIds(orgId, blockerId)) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (!blocked || isArchived(blocked) || isClosedStatus(blocked.status)) continue;
    if (blocked.assigneeId === null) continue;
    if ((await depRepo.listOpenBlockerIds(orgId, blockedId)).length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "Your issue is unblocked",
      body: `Issue #${blocked.number} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

export function registerDependencyListeners(): Unsubscribe {
  const offs = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];
  return () => {
    for (const off of offs) off();
  };
}
